using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Analytic.Interpolation;
internal sealed class MomentExponentialCoercivityDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The complete actual-K moment certificate.",
        H("Original full-kernel certificate source"), Blocks(
            Describe.Lean(DescribeId.Create("exponential-prefix-gamma-coercivity"),
                DeclarationHandle.Create("D5/S3/Analytic/Interpolation/MomentExponentialCoercivity.exponential_prefix_gamma_coercivity"),
                H("Division-free Gamma coercivity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For arbitrary finite complex atoms in [0,D], D>=0, lambda>0, and vanishing mass and first moment, let E be the full prefix energy and E_G the ramp energy on [0,D]. Then (E+lambda^2 E_G) Re Q_lambda >= 2lambda E^2. Polarizing the existing square FTC gives the mixed primitive identity; the integral of norm(response-r(prefix-lambda ramp)) squared is nonnegative for every real r. Its discriminant gives E^2<=C H. The causal Gram identity Re Q_lambda=2lambda H+norm(response(D))^2 retains the nonnegative endpoint square. No energy division is used."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exponential-prefix-kernel-nonneg"),
                DeclarationHandle.Create("D5/S3/Analytic/Interpolation/MomentExponentialCoercivity.exponential_prefix_kernel_nonneg"),
                H("Nonnegative exponential atomic form"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The existing causal Gram identity directly gives Re Q_lambda>=0 for every finite complex family supported in [0,D], D>=0 and lambda>0, without a moment hypothesis. This consumed helper permits enlargement of the Gamma denominator and handles the zero-energy branch of the finite head."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exponential-prefix-gamma-gap-coercivity"),
                DeclarationHandle.Create("D5/S3/Analytic/Interpolation/MomentExponentialCoercivity.exponential_prefix_gamma_gap_coercivity"),
                H("Gamma coercivity with the actual moment gap"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For D>0, q>=1 and atomic moments 0,...,q vanishing, the actual primitive gap delta_q=D^2/(4q(q+1)) gives (1+lambda^2 delta_q) E Re Q_lambda>=2lambda E^2. The Gamma certificate and the consumed primitive-gap supplier apply to the same finite complex family. Empty, repeated, cancelling and zero-energy families remain in scope."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("moment-exponential-prefix-coercivity"),
                DeclarationHandle.Create("D5/S3/Analytic/Interpolation/MomentExponentialCoercivity.moment_exponential_prefix_coercivity"),
                H("moment exponential prefix coercivity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The moment-exponential theorem supplies the quantitative exponential bound. Its existing primitive-gap/causal proof supplies 2lambda(1-lambda^2 delta_q)E as a lower bound for the actual exponential atomic quadratic."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("causal-prefix-deficit"),
                DeclarationHandle.Create("D5/S3/Analytic/Interpolation/MomentExponentialCoercivity.causal_prefix_deficit"),
                H("causal prefix deficit"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For arbitrary zero-mass finite complex atoms in [0,D], E-Re Q_exp(1/2) equals one quarter of the integral on [0,D] of the actual resolvent norm squared, plus one quarter of its endpoint norm squared. The owner-local causal Gram and right-FTC square identities prove the normalization directly."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exponential-prefix-deficit-nonneg"),
                DeclarationHandle.Create("D5/S3/Analytic/Interpolation/MomentExponentialCoercivity.exponential_prefix_deficit_nonneg"),
                H("exponential prefix deficit nonneg"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The preceding literal causal-square formula gives a nonnegative exponential prefix deficit without a first-moment or spectral premise."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-prefix-primitive-gap"),
                DeclarationHandle.Create("D5/S3/Analytic/Interpolation/MomentExponentialCoercivity.actual_prefix_primitive_gap"),
                H("actual prefix primitive gap"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The existing complex_L2_moment_primitive_gap is consumed with the actual prefix. Atomic degrees 0,...,q imply prefix degrees 0,...,q-1, yielding integral norm(ramp)^2<=delta_q E. This is reuse-only."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("growing-primitive-identity"),
                DeclarationHandle.Create("D5/S3/Analytic/Interpolation/MomentExponentialCoercivity.growing_primitive_identity"),
                H("growing primitive identity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The literal growing-exponential atomic form equals -E+(1/4)integral norm(G)^2+(1/16)H(G), initially with H(G) in causal triangular form. The actual G is integral_0^t prefix and both endpoints vanish. The existing finite causal Gram and primitive-exponential proof bodies require only lambda nonzero, so their telescopes are generalized accordingly and applied at lambda=-1/2. Integrating-factor right FTC identifies the second causal response with the actual growing convolution of G. The square FTC supplies the exact triangle expression; no positivity of the growing exponential is asserted."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-prefix-primitive-realization"),
                DeclarationHandle.Create("D5/S3/Analytic/Interpolation/MomentExponentialCoercivity.actual_prefix_primitive_realization"),
                H("actual prefix primitive realization"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The owner right-FTC ramp identity identifies the actual integral primitive at every t>=0 with sum_i a_i max(t-x_i,0), including repeated and endpoint atoms. This is an export of retained proof, consumed by the continuum realization."))),
